1	import { useMemo, useCallback, useState, useEffect } from 'react';
2	import { useTranslation } from 'react-i18next';
3	import { useDropzone } from 'react-dropzone';
4	import { useCreateMode } from '@/features/create-mode/model/useCreateMode';
5	import { AgentIcon } from '@/shared/components/AgentIcon';
6	import { useUserSystem } from '@/shared/hooks/useUserSystem';
7	import WYSIWYGEditor from '@/shared/components/WYSIWYGEditor';
8	import { useCreateWorkspace } from '@/shared/hooks/useCreateWorkspace';
9	import { useCreateAttachments } from '@/shared/hooks/useCreateAttachments';
10	import { useExecutorConfig } from '@/shared/hooks/useExecutorConfig';
11	import { saveProjectRepoDefaults } from '@/shared/hooks/useProjectRepoDefaults';
12	import { getSortedExecutorVariantKeys } from '@/shared/lib/executor';
13	import {
14	  toPrettyCase,
15	  splitMessageToTitleDescription,
16	} from '@/shared/lib/string';
17	import type { BaseCodingAgent, Repo } from 'shared/types';
18	import { CreateChatBox } from '@vibe/ui/components/CreateChatBox';
19	import { SettingsDialog } from '@/shared/dialogs/settings/SettingsDialog';
20	import { CreateModeRepoPickerBar } from './CreateModeRepoPickerBar';
21	import { ModelSelectorContainer } from '@/shared/components/ModelSelectorContainer';
22	
23	function getRepoDisplayName(repo: Repo) {
24	  return repo.display_name || repo.name;
25	}
26	
27	const BRANCH_LABEL_MAX_CHARS = 15;
28	
29	function truncateBranchLabel(branch: string) {
30	  return branch.length > BRANCH_LABEL_MAX_CHARS
31	    ? `${branch.slice(0, BRANCH_LABEL_MAX_CHARS)}...`
32	    : branch;
33	}
34	
35	interface CreateChatBoxContainerProps {
36	  onWorkspaceCreated: (workspaceId: string) => void;
37	}
38	
39	export function CreateChatBoxContainer({
40	  onWorkspaceCreated,
41	}: CreateChatBoxContainerProps) {
42	  const { t } = useTranslation('common');
43	  const { profiles, config } = useUserSystem();
44	  const {
45	    repos,
46	    targetBranches,
47	    message,
48	    setMessage,
49	    clearDraft,
50	    hasInitialValue,
51	    hasResolvedInitialRepoDefaults,
52	    linkedIssue,
53	    clearLinkedIssue,
54	    preferredExecutorConfig,
55	    executorConfig: draftConfig,
56	    setExecutorConfig: setDraftConfig,
57	    attachments: draftAttachments,
58	    setAttachments: setDraftAttachments,
59	  } = useCreateMode();
60	
61	  const { createWorkspace } = useCreateWorkspace();
62	  const hasSelectedRepos = repos.length > 0;
63	  const [hasAttemptedSubmit, setHasAttemptedSubmit] = useState(false);
64	  const [hasInitializedStep, setHasInitializedStep] = useState(false);
65	  const [isSelectingRepos, setIsSelectingRepos] = useState(true);
66	
67	  useEffect(() => {
68	    if (!hasInitialValue || hasInitializedStep) return;
69	    if (!hasSelectedRepos && !hasResolvedInitialRepoDefaults) return;
70	
71	    setIsSelectingRepos(!hasSelectedRepos);
72	    setHasInitializedStep(true);
73	  }, [
74	    hasInitialValue,
75	    hasInitializedStep,
76	    hasSelectedRepos,
77	    hasResolvedInitialRepoDefaults,
78	  ]);
79	
80	  const showRepoPickerStep = !hasSelectedRepos || isSelectingRepos;
81	  const showChatStep = hasSelectedRepos && !isSelectingRepos;
82	
83	  // Attachment handling - insert markdown and track attachment IDs
84	  const handleInsertMarkdown = useCallback(
85	    (markdown: string) => {
86	      const newMessage = message.trim()
87	        ? `${message}\n\n${markdown}`
88	        : markdown;
89	      setMessage(newMessage);
90	    },
91	    [message, setMessage]
92	  );
93	
94	  const { uploadFiles, getAttachmentIds, clearAttachments, localAttachments } =
95	    useCreateAttachments(
96	      handleInsertMarkdown,
97	      draftAttachments,
98	      setDraftAttachments
99	    );
100	
101	  const onDrop = useCallback(
102	    (acceptedFiles: File[]) => {
103	      if (acceptedFiles.length > 0) {
104	        uploadFiles(acceptedFiles);
105	      }
106	    },
107	    [uploadFiles]
108	  );
109	
110	  const { getRootProps, getInputProps, isDragActive } = useDropzone({
111	    onDrop,
112	    disabled: createWorkspace.isPending || !hasSelectedRepos,
113	    noClick: true,
114	    noKeyboard: true,
115	  });
116	
117	  const scratchConfig = useMemo(() => {
118	    if (!hasInitialValue) return undefined; // still loading
119	    return draftConfig ?? null;
120	  }, [hasInitialValue, draftConfig]);
121	
122	  const {
123	    executorConfig,
124	    effectiveExecutor,
125	    selectedVariant,
126	    executorOptions,
127	    variantOptions,
128	    presetOptions,
129	    setOverrides: setExecutorOverrides,
130	  } = useExecutorConfig({
131	    profiles,
132	    lastUsedConfig: preferredExecutorConfig,
133	    scratchConfig,
134	    configExecutorProfile: config?.executor_profile,
135	    onPersist: (cfg) => setDraftConfig(cfg),
136	  });
137	
138	  const repoId = repos.length === 1 ? repos[0]?.id : undefined;
139	  const repoSummaryLabel = useMemo(() => {
140	    if (repos.length === 1) {
141	      const repo = repos[0];
142	      if (!repo) return '0 repositories selected';
143	      const selectedBranch = targetBranches[repo.id];
144	      const branch = selectedBranch
145	        ? truncateBranchLabel(selectedBranch)
146	        : 'Select branch';
147	      return `${getRepoDisplayName(repo)} · ${branch}`;
148	    }
149	
150	    return `${repos.length} repositories selected`;
151	  }, [repos, targetBranches]);
152	
153	  const repoSummaryTitle = useMemo(
154	    () =>
155	      repos
156	        .map((repo) => {
157	          const branch = targetBranches[repo.id] ?? 'Select branch';
158	          return `${getRepoDisplayName(repo)} (${branch})`;
159	        })
160	        .join('\n'),
161	    [repos, targetBranches]
162	  );
163	
164	  const hasSelectedBranchesForAllRepos = repos.every(
165	    (repo) => !!targetBranches[repo.id]
166	  );
167	
168	  // Determine if we can submit
169	  const canSubmit =
170	    hasSelectedRepos &&
171	    hasSelectedBranchesForAllRepos &&
172	    message.trim().length > 0 &&
173	    effectiveExecutor !== null;
174	
175	  const handlePresetSelect = (presetId: string | null) => {
176	    if (!effectiveExecutor) return;
177	    setDraftConfig({
178	      ...draftConfig,
179	      executor: effectiveExecutor,
180	      variant: presetId,
181	    });
182	  };
183	
184	  const handleCustomise = () => {
185	    SettingsDialog.show({ initialSection: 'agents' });
186	  };
187	
188	  // Handle executor change - use saved variant if switching to default executor
189	  const handleExecutorChange = useCallback(
190	    (executor: BaseCodingAgent) => {
191	      const executorProfile = profiles?.[executor];
192	      if (!executorProfile) {
193	        setDraftConfig({ executor, variant: null });
194	        return;
195	      }
196	
197	      const variants = getSortedExecutorVariantKeys(executorProfile);
198	      let targetVariant: string | null = null;
199	
200	      // If switching to user's default executor, use their saved variant
201	      if (
202	        config?.executor_profile?.executor === executor &&
203	        config?.executor_profile?.variant
204	      ) {
205	        const savedVariant = config.executor_profile.variant;
206	        if (variants.includes(savedVariant)) {
207	          targetVariant = savedVariant;
208	        }
209	      }
210	
211	      // Fallback to DEFAULT or first available
212	      if (!targetVariant) {
213	        targetVariant = variants.includes('DEFAULT')
214	          ? 'DEFAULT'
215	          : (variants[0] ?? null);
216	      }
217	
218	      setDraftConfig({ executor, variant: targetVariant });
219	    },
220	    [profiles, setDraftConfig, config?.executor_profile]
221	  );
222	
223	  // Handle submit
224	  const handleSubmit = useCallback(async () => {
225	    setHasAttemptedSubmit(true);
226	    if (!canSubmit || !executorConfig) return;
227	
228	    const { title } = splitMessageToTitleDescription(message);
229	    const data = {
230	      executor_config: executorConfig,
231	      name: title,
232	      prompt: message,
233	      repos: repos.map((r) => ({
234	        repo_id: r.id,
235	        target_branch: targetBranches[r.id]!,
236	      })),
237	      linked_issue: linkedIssue
238	        ? {
239	            remote_project_id: linkedIssue.remoteProjectId,
240	            issue_id: linkedIssue.issueId,
241	          }
242	        : null,
243	      attachment_ids: getAttachmentIds(),
244	    };
245	    const linkToIssue = linkedIssue
246	      ? {
247	          remoteProjectId: linkedIssue.remoteProjectId,
248	          issueId: linkedIssue.issueId,
249	        }
250	      : undefined;
251	
252	    const result = await createWorkspace.mutateAsync({
253	      data,
254	      linkToIssue,
255	    });
256	
257	    if (result.workspace) {
258	      onWorkspaceCreated(result.workspace.id);
259	    }
260	
261	    if (linkedIssue?.remoteProjectId) {
262	      saveProjectRepoDefaults(linkedIssue.remoteProjectId, data.repos).catch(
263	        (err) => console.warn('Failed to save project repo defaults:', err)
264	      );
265	    }
266	
267	    clearAttachments();
268	    await clearDraft();
269	  }, [
270	    canSubmit,
271	    executorConfig,
272	    message,
273	    repos,
274	    targetBranches,
275	    createWorkspace,
276	    onWorkspaceCreated,
277	    getAttachmentIds,
278	    clearAttachments,
279	    clearDraft,
280	    linkedIssue,
281	  ]);
282	
283	  // Determine error to display
284	  const displayError =
285	    hasAttemptedSubmit && repos.length === 0
286	      ? 'Add at least one repository to create a workspace'
287	      : hasAttemptedSubmit && !hasSelectedBranchesForAllRepos
288	        ? 'Select a branch for every repository before creating a workspace'
289	        : createWorkspace.error
290	          ? createWorkspace.error instanceof Error
291	            ? createWorkspace.error.message
292	            : 'Failed to create workspace'
293	          : null;
294	
295	  // Wait for initial value to be applied before rendering
296	  // This ensures the editor mounts with content ready, so autoFocus works correctly
297	  if (!hasInitialValue) {
298	    return null;
299	  }
300	
301	  return (
302	    <div className="relative flex flex-1 flex-col bg-primary h-full">
303	      <div className="flex flex-1 items-center justify-center px-base">
304	        <div className="flex w-chat max-w-full flex-col gap-base">
305	          {showRepoPickerStep && (
306	            <>
307	              <h2 className="mb-double text-center text-4xl font-medium tracking-tight text-high">
308	                {t('createMode.headings.repoStep')}
309	              </h2>
310	              <CreateModeRepoPickerBar
311	                onContinueToPrompt={() => setIsSelectingRepos(false)}
312	              />
313	            </>
314	          )}
315	
316	          {showChatStep && (
317	            <>
318	              <h2 className="mb-double text-center text-4xl font-medium tracking-tight text-high">
319	                {t('createMode.headings.chatStep')}
320	              </h2>
321	
322	              <div className="flex justify-center @container">
323	                <CreateChatBox
324	                  editor={{
325	                    value: message,
326	                    onChange: setMessage,
327	                  }}
