411	          draft?.editor.editor_type === EditorType.CURSOR) && (
412	          <SettingsCheckbox
413	            id="auto-install-extension"
414	            label={t('settings.general.editor.autoInstallExtension.label')}
415	            description={t(
416	              'settings.general.editor.autoInstallExtension.helper'
417	            )}
418	            checked={draft?.editor.auto_install_extension ?? true}
419	            onChange={(checked) =>
420	              updateDraft({
421	                editor: {
422	                  ...draft!.editor,
423	                  auto_install_extension: checked,
424	                },
425	              })
426	            }
427	          />
428	        )}
429	      </SettingsCard>
430	
431	      {/* Default Coding Agent */}
432	      <SettingsCard
433	        title={t('settings.general.taskExecution.title')}
434	        description={t('settings.general.taskExecution.description')}
435	      >
436	        <SettingsField
437	          label={t('settings.general.taskExecution.executor.label')}
438	          description={t('settings.general.taskExecution.executor.helper')}
439	        >
440	          <div className="grid grid-cols-2 gap-2">
441	            <DropdownMenu>
442	              <DropdownMenuTrigger asChild>
443	                <DropdownMenuTriggerButton
444	                  label={
445	                    draft?.executor_profile?.executor
446	                      ? toPrettyCase(draft.executor_profile.executor)
447	                      : t('settings.agents.selectAgent')
448	                  }
449	                  className="w-full justify-between"
450	                  disabled={!profiles}
451	                />
452	              </DropdownMenuTrigger>
453	              <DropdownMenuContent className="w-[var(--radix-dropdown-menu-trigger-width)]">
454	                {executorOptions.map((option) => (
455	                  <DropdownMenuItem
456	                    key={option.value}
457	                    onClick={() => {
458	                      const variants = profiles?.[option.value];
459	                      const variantKeys = variants
460	                        ? getExecutorVariantKeys(variants)
461	                        : [];
462	                      const keepCurrentVariant =
463	                        variantKeys.length > 0 &&
464	                        draft?.executor_profile?.variant &&
465	                        variantKeys.includes(draft.executor_profile.variant);
466	
467	                      const newProfile: ExecutorProfileId = {
468	                        executor: option.value as BaseCodingAgent,
469	                        variant: keepCurrentVariant
470	                          ? draft!.executor_profile!.variant
471	                          : null,
472	                      };
473	                      updateDraft({ executor_profile: newProfile });
474	                    }}
475	                  >
476	                    {option.label}
477	                  </DropdownMenuItem>
478	                ))}
479	              </DropdownMenuContent>
480	            </DropdownMenu>
481	
482	            {hasVariants ? (
483	              <DropdownMenu>
484	                <DropdownMenuTrigger asChild>
485	                  <DropdownMenuTriggerButton
486	                    label={
487	                      draft?.executor_profile?.variant
488	                        ? toPrettyCase(draft.executor_profile.variant)
489	                        : t('settings.general.taskExecution.defaultLabel')
490	                    }
491	                    className="w-full justify-between"
492	                  />
493	                </DropdownMenuTrigger>
494	                <DropdownMenuContent className="w-[var(--radix-dropdown-menu-trigger-width)]">
495	                  {variantOptions.map((variantLabel) => (
496	                    <DropdownMenuItem
497	                      key={variantLabel}
498	                      onClick={() => {
499	                        const newProfile: ExecutorProfileId = {
500	                          executor: draft!.executor_profile!.executor,
501	                          variant: variantLabel,
502	                        };
503	                        updateDraft({ executor_profile: newProfile });
504	                      }}
505	                    >
506	                      {toPrettyCase(variantLabel)}
507	                    </DropdownMenuItem>
508	                  ))}
509	                </DropdownMenuContent>
510	              </DropdownMenu>
511	            ) : selectedAgentProfile ? (
512	              <button
513	                disabled
514	                className={cn(
515	                  'flex items-center justify-between w-full px-base py-half rounded-sm border border-border bg-secondary',
516	                  'text-base text-low opacity-50 cursor-not-allowed'
517	                )}
518	              >
519	                <span className="truncate">
520	                  {t('settings.general.taskExecution.defaultLabel')}
521	                </span>
522	              </button>
523	            ) : null}
524	          </div>
525	        </SettingsField>
526	      </SettingsCard>
527	
528	      {/* Git */}
529	      <SettingsCard
530	        title={t('settings.general.git.title')}
531	        description={t('settings.general.git.description')}
532	      >
533	        <SettingsField
534	          label={t('settings.general.git.branchPrefix.label')}
535	          error={branchPrefixError}
536	          description={
537	            <>
538	              {t('settings.general.git.branchPrefix.helper')}{' '}
539	              {draft?.git_branch_prefix ? (
540	                <>
541	                  {t('settings.general.git.branchPrefix.preview')}{' '}
542	                  <code className="text-xs bg-secondary px-1 py-0.5 rounded">
543	                    {t('settings.general.git.branchPrefix.previewWithPrefix', {
544	                      prefix: draft.git_branch_prefix,
545	                    })}
546	                  </code>
547	                </>
548	              ) : (
549	                <>
550	                  {t('settings.general.git.branchPrefix.preview')}{' '}
551	                  <code className="text-xs bg-secondary px-1 py-0.5 rounded">
552	                    {t('settings.general.git.branchPrefix.previewNoPrefix')}
553	                  </code>
554	                </>
555	              )}
556	            </>
557	          }
558	        >
559	          <SettingsInput
560	            value={draft?.git_branch_prefix ?? ''}
561	            onChange={(value) => {
562	              const trimmed = value.trim();
563	              updateDraft({ git_branch_prefix: trimmed });
564	              setBranchPrefixError(validateBranchPrefix(trimmed));
565	            }}
566	            placeholder={t('settings.general.git.branchPrefix.placeholder')}
567	            error={!!branchPrefixError}
568	          />
569	        </SettingsField>
570	
571	        <SettingsField
572	          label={t('settings.general.git.workspaceDir.label')}
573	          description={t('settings.general.git.workspaceDir.helper')}
574	        >
575	          <div className="flex gap-2">
576	            <div className="flex-1">
577	              <SettingsInput
578	                value={draft?.workspace_dir ?? ''}
579	                onChange={(value) =>
580	                  updateDraft({ workspace_dir: value || null })
581	                }
582	                placeholder={t('settings.general.git.workspaceDir.placeholder')}
583	              />
584	            </div>
585	            <PrimaryButton
586	              variant="tertiary"
587	              onClick={handleBrowseWorkspaceDir}
588	            >
589	              <FolderSimpleIcon className="size-icon-sm" weight="bold" />
590	              {t('settings.general.git.workspaceDir.browse')}
591	            </PrimaryButton>
592	          </div>
593	        </SettingsField>
594	      </SettingsCard>
595	
596	      {/* Pull Requests */}
597	      <SettingsCard
598	        title={t('settings.general.pullRequests.title')}
599	        description={t('settings.general.pullRequests.description')}
600	      >
601	        <SettingsCheckbox
602	          id="pr-auto-description"
603	          label={t('settings.general.pullRequests.autoDescription.label')}
604	          description={t(
605	            'settings.general.pullRequests.autoDescription.helper'
606	          )}
607	          checked={draft?.pr_auto_description_enabled ?? false}
608	          onChange={(checked) =>
609	            updateDraft({ pr_auto_description_enabled: checked })
610	          }
611	        />
612	
613	        <SettingsCheckbox
614	          id="use-custom-prompt"
615	          label={t('settings.general.pullRequests.customPrompt.useCustom')}
616	          checked={draft?.pr_auto_description_prompt != null}
617	          onChange={(checked) => {
618	            if (checked) {
619	              updateDraft({
620	                pr_auto_description_prompt: DEFAULT_PR_DESCRIPTION_PROMPT,
621	              });
622	            } else {
623	              updateDraft({ pr_auto_description_prompt: null });
624	            }
625	          }}
626	        />
627	
628	        <SettingsField
629	          label=""
630	          description={t('settings.general.pullRequests.customPrompt.helper')}
631	        >
632	          <SettingsTextarea
633	            value={
634	              draft?.pr_auto_description_prompt ?? DEFAULT_PR_DESCRIPTION_PROMPT
635	            }
636	            onChange={(value) =>
637	              updateDraft({ pr_auto_description_prompt: value })
638	            }
639	            disabled={draft?.pr_auto_description_prompt == null}
640	          />
641	        </SettingsField>
642	      </SettingsCard>
643	
644	      {/* Commits */}
645	      <SettingsCard
646	        title={t('settings.general.commits.title')}
647	        description={t('settings.general.commits.description')}
648	      >
649	        <SettingsCheckbox
650	          id="commit-reminder"
651	          label={t('settings.general.commits.reminder.label')}
652	          description={t('settings.general.commits.reminder.helper')}
653	          checked={draft?.commit_reminder_enabled ?? true}
654	          onChange={(checked) =>
655	            updateDraft({ commit_reminder_enabled: checked })
656	          }
657	        />
658	
659	        {draft?.commit_reminder_enabled && (
660	          <>
661	            <SettingsCheckbox
662	              id="use-custom-commit-prompt"
663	              label={t('settings.general.commits.customPrompt.useCustom')}
664	              checked={draft?.commit_reminder_prompt != null}
665	              onChange={(checked) => {
666	                if (checked) {
667	                  updateDraft({
668	                    commit_reminder_prompt: DEFAULT_COMMIT_REMINDER_PROMPT,
669	                  });
670	                } else {
671	                  updateDraft({ commit_reminder_prompt: null });
672	                }
673	              }}
674	            />
675	
676	            <SettingsField
677	              label=""
678	              description={t('settings.general.commits.customPrompt.helper')}
679	            >
680	              <SettingsTextarea
681	                value={
682	                  draft?.commit_reminder_prompt ??
683	                  DEFAULT_COMMIT_REMINDER_PROMPT
684	                }
685	                onChange={(value) =>
686	                  updateDraft({ commit_reminder_prompt: value })
687	                }
688	                disabled={draft?.commit_reminder_prompt == null}
689	              />
690	            </SettingsField>
691	          </>
692	        )}
693	      </SettingsCard>
694	
695	      {/* Notifications */}
696	      <SettingsCard
697	        title={t('settings.general.notifications.title')}
698	        description={t('settings.general.notifications.description')}
699	      >
700	        <SettingsCheckbox
701	          id="sound-enabled"
702	          label={t('settings.general.notifications.sound.label')}
703	          description={t('settings.general.notifications.sound.helper')}
704	          checked={draft?.notifications.sound_enabled ?? false}
705	          onChange={(checked) =>
706	            updateDraft({
707	              notifications: {
708	                ...draft!.notifications,
709	                sound_enabled: checked,
710	              },
711	            })
712	          }
713	        />
714	
715	        {draft?.notifications.sound_enabled && (
716	          <div className="ml-7 space-y-2">
717	            <label className="text-sm font-medium text-normal">
718	              {t('settings.general.notifications.sound.fileLabel')}
719	            </label>
720	            <div className="flex gap-2">
721	              <div className="flex-1">
722	                <SettingsSelect
723	                  value={draft.notifications.sound_file}
724	                  options={soundOptions}
725	                  onChange={(value: SoundFile) =>
726	                    updateDraft({
727	                      notifications: {
728	                        ...draft.notifications,
729	                        sound_file: value,
730	                      },
731	                    })
732	                  }
733	                  placeholder={t(
734	                    'settings.general.notifications.sound.filePlaceholder'
735	                  )}
736	                />
737	              </div>
738	              <IconButton
739	                icon={SpeakerHighIcon}
740	                onClick={() => previewSound(draft.notifications.sound_file)}
741	                aria-label="Preview sound"
742	                title="Preview sound"
743	              />
744	            </div>
745	            <p className="text-sm text-low">
746	              {t('settings.general.notifications.sound.fileHelper')}
747	            </p>
748	          </div>
749	        )}
750	
751	        <SettingsCheckbox
752	          id="push-notifications"
753	          label={t('settings.general.notifications.push.label')}
754	          description={t('settings.general.notifications.push.helper')}
755	          checked={draft?.notifications.push_enabled ?? false}
756	          onChange={(checked) =>
757	            updateDraft({
758	              notifications: {
759	                ...draft!.notifications,
760	                push_enabled: checked,
761	              },
762	            })
763	          }
764	        />
765	      </SettingsCard>
766	
767	      {/* Message Input */}
768	      <SettingsCard
769	        title={t('settings.general.messageInput.title')}
770	        description={t('settings.general.messageInput.description')}
771	      >
772	        <SettingsField
773	          label={t('settings.general.messageInput.shortcut.label')}
774	          description={t('settings.general.messageInput.shortcut.helper')}
775	        >
776	          <SettingsSelect
777	            value={draft?.send_message_shortcut ?? 'ModifierEnter'}
778	            options={[
779	              {
780	                value: 'ModifierEnter' as SendMessageShortcut,
781	                label: `${getModifierKey()}+Enter`,
782	              },
783	              {
784	                value: 'Enter' as SendMessageShortcut,
785	                label: t('settings.general.messageInput.shortcut.enterLabel'),
786	              },
787	            ]}
788	            onChange={(value: SendMessageShortcut) =>
789	              updateDraft({ send_message_shortcut: value })
790	            }
791	          />
792	        </SettingsField>
793	      </SettingsCard>
794	
795	      {/* Privacy */}
796	      <SettingsCard
797	        title={t('settings.general.privacy.title')}
798	        description={t('settings.general.privacy.description')}
799	      >
800	        <SettingsCheckbox
801	          id="analytics-enabled"
802	          label={t('settings.general.privacy.telemetry.label')}
803	          description={t('settings.general.privacy.telemetry.helper')}
804	          checked={draft?.analytics_enabled ?? false}
805	          onChange={(checked) => updateDraft({ analytics_enabled: checked })}
806	        />
807	      </SettingsCard>
808	
809	      {/* Task Templates */}
810	      <SettingsCard
811	        title={t('settings.general.taskTemplates.title')}
812	        description={t('settings.general.taskTemplates.description')}
813	      >
814	        <TagManager />
815	      </SettingsCard>
816	
817	      {/* Safety */}
818	      <SettingsCard
819	        title={t('settings.general.safety.title')}
820	        description={t('settings.general.safety.description')}
821	      >
822	        <div className="flex items-center justify-between">
823	          <div>
824	            <p className="text-sm font-medium text-normal">
825	              {t('settings.general.safety.onboarding.title')}
826	            </p>
827	            <p className="text-sm text-low">
828	              {t('settings.general.safety.onboarding.description')}
829	            </p>
830	          </div>
831	          <PrimaryButton
832	            variant="tertiary"
833	            value={t('settings.general.safety.onboarding.button')}
834	            onClick={resetOnboarding}
835	          />
836	        </div>
837	      </SettingsCard>
838	
839	      <SettingsSaveBar
840	        show={hasUnsavedChanges}
